import {Avatar, Banner, CodeBlock, Dialog, Grid, List, Selector, Switch, TabList, Text} from '@astryxdesign/core';

export function Legacy({open}: {open: boolean}) {
  return (
    <>
      <Text color='accent'>Hi</Text>
      <Switch label="On" labelSpacing='hug' />
      <Avatar name="Ada" size='md' />
      <TabList />
      <Dialog isOpen={open} position="left" title="Side" />
      <Grid columns={{
        minWidth: 200,
        repeat: 'fit'
      }} />
      <Banner status="info" title="More" collapsible={{
        defaultIsOpen: true
      }} />
      <Selector label="Pick" options={[]} emptySearchResultsText="None" />
      <List edgeCompensation />
      <CodeBlock code="x" tokenizer={(s: string) => [s]} />
    </>
  );
}

import {Badge, Banner, Button, Dialog, Selector, TopNav} from "@astryxdesign/core";

export function LegacyXds({open}: {open: boolean}) {
  return (
    <>
      <TopNav heading="Home" />
      <Banner status="info" title="Heads up" endContent={<Button label="Ok" />} />
      <Selector label="Fruit" options={[{value: 'a', label: 'Apple'}]} />
      <Dialog isOpen={open} onOpenChange={() => {}} title="Hello" />
      <Button label="Next" endContent={<Badge dot />} />
    </>
  );
}
